#!/usr/bin/env node
const { readFileSync, existsSync } = require("fs")
const { loadAll } = require("js-yaml")

const schema = JSON.parse(readFileSync(join(__dirname, "session-yaml-schema.json"), "utf-8"))
const tsPat = /^\d{1,2}\/\d{1,2}\/\d{4}, \d{1,2}:\d{2}:\d{2}\.\d{3} (AM|PM) [A-Z]+\+?\d*/
const durPat = /^\d+(\.\d+)?(ms|s)$/

const errors = []
function check(cond, msg) { if (!cond) errors.push(msg) }
function isObj(v) { return typeof v === "object" && v !== null && !Array.isArray(v) }

function validateStep(step, path, docIdx) {
  check(typeof step === "object" && step !== null, `${path}: must be an object`)
  if (!step) return
  for (const k of Object.keys(step)) {
    if (!["agent","model","thinking","thinking_duration","thinking_duration_ms","time","tool_calls","response","duration","duration_ms"].includes(k)) {
      errors.push(`${path}: unexpected key "${k}"`)
    }
  }
  if (step.agent != null) check(typeof step.agent === "string", `${path}.agent: must be string`)
  if (step.model != null) {
    check(isObj(step.model), `${path}.model: must be object`)
    if (isObj(step.model)) {
      check(typeof step.model.id === "string", `${path}.model.id: must be string`)
      check(typeof step.model.provider === "string", `${path}.model.provider: must be string`)
    }
  }
  if (step.thinking != null) check(typeof step.thinking === "string", `${path}.thinking: must be string`)
  if (step.thinking_duration != null) check(durPat.test(step.thinking_duration), `${path}.thinking_duration: bad format "${step.thinking_duration}"`)
  if (step.thinking_duration_ms != null) check(typeof step.thinking_duration_ms === "number", `${path}.thinking_duration_ms: must be number`)
  check(step.time != null || step.response != null, `${path}: must have "time" or "response"`)
  if (step.time != null) check(tsPat.test(step.time), `${path}.time: bad timestamp "${step.time}"`)
  if (step.response != null) check(typeof step.response === "string", `${path}.response: must be string`)
  if (step.duration != null) check(durPat.test(step.duration), `${path}.duration: bad format "${step.duration}"`)
  if (step.duration_ms != null) check(typeof step.duration_ms === "number", `${path}.duration_ms: must be number`)
  if (step.tool_calls != null) {
    check(Array.isArray(step.tool_calls), `${path}.tool_calls: must be array`)
    if (Array.isArray(step.tool_calls)) {
      step.tool_calls.forEach((tc, i) => validateToolCall(tc, `${path}.tool_calls[${i}]`, docIdx))
    }
  }
}

function validateToolCall(tc, path, docIdx) {
  check(isObj(tc), `${path}: must be object`)
  if (!isObj(tc)) return
  for (const k of Object.keys(tc)) {
    if (!["tool","args","result","error"].includes(k)) errors.push(`${path}: unexpected key "${k}"`)
  }
  check(typeof tc.tool === "string", `${path}.tool: must be string`)
  check(isObj(tc.args) || tc.args === "", `${path}.args: must be object or empty string`)
  if (tc.result != null) check(typeof tc.result === "string", `${path}.result: must be string`)
  if (tc.error != null) check(typeof tc.error === "string", `${path}.error: must be string`)
}

function validateTurn(doc, idx) {
  // Determine which doc type
  if (isObj(doc.session)) {
    // Session header doc
    for (const k of Object.keys(doc)) {
      if (!["session","model","title"].includes(k)) errors.push(`doc[${idx}]: unexpected top-level key "${k}"`)
    }
    check(isObj(doc.session), `doc[${idx}].session: must be object`)
    if (isObj(doc.session)) {
      const s = doc.session
      for (const k of Object.keys(s)) {
        if (!["id","created","updated","compacted"].includes(k)) errors.push(`doc[${idx}].session: unexpected key "${k}"`)
      }
      check(typeof s.id === "string", `doc[${idx}].session.id: must be string`)
      check(s.id.startsWith("ses_"), `doc[${idx}].session.id: must start with "ses_"`)
      check(tsPat.test(s.created), `doc[${idx}].session.created: bad timestamp "${s.created}"`)
      check(tsPat.test(s.updated), `doc[${idx}].session.updated: bad timestamp "${s.updated}"`)
      if (s.compacted != null) check(tsPat.test(s.compacted), `doc[${idx}].session.compacted: bad timestamp`)
    }
    check(isObj(doc.model), `doc[${idx}].model: must be object`)
    if (isObj(doc.model)) {
      check(typeof doc.model.id === "string", `doc[${idx}].model.id: must be string`)
      check(typeof doc.model.provider === "string", `doc[${idx}].model.provider: must be string`)
    }
    if (doc.title != null) check(typeof doc.title === "string", `doc[${idx}].title: must be string`)
  } else if (isObj(doc.user)) {
    // User turn doc
    for (const k of Object.keys(doc)) {
      if (!["user","assistant"].includes(k)) errors.push(`doc[${idx}]: unexpected top-level key "${k}"`)
    }
    const u = doc.user
    for (const k of Object.keys(u)) {
      if (!["text","time"].includes(k)) errors.push(`doc[${idx}].user: unexpected key "${k}"`)
    }
    check(typeof u.text === "string", `doc[${idx}].user.text: must be string`)
    if (u.time != null) check(tsPat.test(u.time), `doc[${idx}].user.time: bad timestamp "${u.time}"`)
    if (doc.assistant != null) {
      check(Array.isArray(doc.assistant), `doc[${idx}].assistant: must be array`)
      if (Array.isArray(doc.assistant)) {
        doc.assistant.forEach((s, i) => validateStep(s, `doc[${idx}].assistant[${i}]`, idx))
      }
    }
  } else {
    errors.push(`doc[${idx}]: unrecognized structure — must be sessionHeader or userTurn`)
  }
}

function main() {
  const args = process.argv.slice(2)
  if (args.length === 0) {
    console.error("Usage: node validate-session-yaml.js <session-yaml-file> [<file2> ...]")
    process.exit(1)
  }
  let totalErrs = 0
  for (const fp of args) {
    if (!existsSync(fp)) { console.error(`File not found: ${fp}`); totalErrs++; continue }
    const content = readFileSync(fp, "utf-8")
    const docName = fp.split("/").pop()
    let docs
    try {
      docs = loadAll(content)
    } catch (e) {
      console.error(`✗ ${docName} — YAML parse error: ${e.message}`)
      totalErrs++
      continue
    }
    errors.length = 0
    docs.forEach((doc, i) => validateTurn(doc, i))
    if (errors.length === 0) {
      console.log(`✓ ${docName} — ${docs.length} documents, all valid`)
    } else {
      console.error(`✗ ${docName} — ${errors.length} error(s):`)
      for (const e of errors) console.error(`    ${e}`)
      totalErrs += errors.length
    }
  }
  process.exit(totalErrs > 0 ? 1 : 0)
}

const { join } = require("path")
main()

