      const startTime = s.turn.startTime ?? ts()
      const pendingFilename = `${turnNum}-pending-${startTime.replace(/[:.]/g, "-")}.yaml`
      writeFileSync(join(baseDir, pendingFilename), buildYAML([s.turn.toFields()]))
    }
  } catch { /* no crash */ }
}

